=== FILE: apb_gpio.v ===
`timescale 1ns/1ps
`default_nettype none

// apb_gpio: APB4 GPIO peripheral with interrupts.
// Implements interface_spec.md per microarchitecture.md.
module apb_gpio #(
    parameter ADDR_WIDTH = 8,
    parameter N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Constant mask of existing pins: bits 0 .. N-1 set.
    localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

    // Register indices (paddr[5:2]).
    localparam [3:0] IDX_DATA_OUT = 4'd0;
    localparam [3:0] IDX_DIR      = 4'd1;
    localparam [3:0] IDX_DATA_IN  = 4'd2;
    localparam [3:0] IDX_RISE     = 4'd3;
    localparam [3:0] IDX_FALL     = 4'd4;
    localparam [3:0] IDX_HIGH     = 4'd5;
    localparam [3:0] IDX_LOW      = 4'd6;
    localparam [3:0] IDX_EN       = 4'd7;
    localparam [3:0] IDX_STATUS   = 4'd8;

    // State
    reg [31:0] data_out_q;
    reg [31:0] dir_q;
    reg [31:0] in_q;
    reg [31:0] in_prev_q;
    reg [31:0] rise_en_q;
    reg [31:0] fall_en_q;
    reg [31:0] high_en_q;
    reg [31:0] low_en_q;
    reg [31:0] int_en_q;
    reg [31:0] status_q;

    // APB decode
    wire       access       = psel & penable;
    wire [3:0] reg_idx      = paddr[5:2];
    wire       addr_aligned = (paddr[1:0] == 2'b00);
    wire       addr_hi_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
    wire       mapped       = addr_aligned & addr_hi_zero & (reg_idx <= IDX_STATUS);
    wire       wr_en        = access & pwrite & mapped;
    wire       rd_en        = access & ~pwrite & mapped;

    assign pready  = 1'b1;
    assign pslverr = access & (~mapped | (pwrite & (reg_idx == IDX_DATA_IN)));

    // Write mask: byte strobes expanded, limited to existing pins.
    wire [31:0] strb_mask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}};
    wire [31:0] wr_mask   = strb_mask & PINS;

    // Input widened to 32 bits with zeros above N.
    wire [31:0] in_w;
    generate
        if (N < 32) begin : g_in_pad
            assign in_w = {{(32-N){1'b0}}, gpio_in};
        end else begin : g_in_full
            assign in_w = gpio_in;
        end
    endgenerate

    // Detection (combinational from the two samples and enables).
    wire [31:0] rise_det   = in_q & ~in_prev_q;
    wire [31:0] fall_det   = ~in_q & in_prev_q;
    wire [31:0] detected   = ((rise_det & rise_en_q) | (fall_det & fall_en_q)
                             | (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
    wire [31:0] clear_mask = (wr_en && (reg_idx == IDX_STATUS)) ? (pwdata & wr_mask) : 32'd0;

    // Read multiplexer
    reg [31:0] rd_mux;
    always @(*) begin
        case (reg_idx)
            IDX_DATA_OUT: rd_mux = data_out_q;
            IDX_DIR:      rd_mux = dir_q;
            IDX_DATA_IN:  rd_mux = in_q;
            IDX_RISE:     rd_mux = rise_en_q;
            IDX_FALL:     rd_mux = fall_en_q;
            IDX_HIGH:     rd_mux = high_en_q;
            IDX_LOW:      rd_mux = low_en_q;
            IDX_EN:       rd_mux = int_en_q;
            IDX_STATUS:   rd_mux = status_q;
            default:      rd_mux = 32'd0;
        endcase
    end

    assign prdata = rd_en ? rd_mux : 32'd0;

    // Sequential state, synchronous active-low reset.
    always @(posedge pclk) begin
        if (!presetn) begin
            data_out_q <= 32'd0;
            dir_q      <= 32'd0;
            in_q       <= 32'd0;
            in_prev_q  <= 32'd0;
            rise_en_q  <= 32'd0;
            fall_en_q  <= 32'd0;
            high_en_q  <= 32'd0;
            low_en_q   <= 32'd0;
            int_en_q   <= 32'd0;
            status_q   <= 32'd0;
        end else begin
            in_q      <= in_w;
            in_prev_q <= in_q;
            // Detection is ORed last: it beats a clear on the same edge.
            status_q  <= (status_q & ~clear_mask) | detected;
            if (wr_en) begin
                case (reg_idx)
                    IDX_DATA_OUT: data_out_q <= (data_out_q & ~wr_mask) | (pwdata & wr_mask);
                    IDX_DIR:      dir_q      <= (dir_q      & ~wr_mask) | (pwdata & wr_mask);
                    IDX_RISE:     rise_en_q  <= (rise_en_q  & ~wr_mask) | (pwdata & wr_mask);
                    IDX_FALL:     fall_en_q  <= (fall_en_q  & ~wr_mask) | (pwdata & wr_mask);
                    IDX_HIGH:     high_en_q  <= (high_en_q  & ~wr_mask) | (pwdata & wr_mask);
                    IDX_LOW:      low_en_q   <= (low_en_q   & ~wr_mask) | (pwdata & wr_mask);
                    IDX_EN:       int_en_q   <= (int_en_q   & ~wr_mask) | (pwdata & wr_mask);
                    default: ; // DATA_IN is read only; INTR_STATUS handled above
                endcase
            end
        end
    end

    assign gpio_out = data_out_q[N-1:0];
    assign gpio_oe  = dir_q[N-1:0];
    assign irq      = |(status_q & int_en_q);

`ifdef FORMAL
    // Design-intent assertions (combinational invariants).
    always @(*) begin
        assert (pready == 1'b1);
        if (!access) begin
            assert (prdata == 32'd0);
            assert (pslverr == 1'b0);
        end
        if (access && !mapped) begin
            assert (prdata == 32'd0);
            assert (pslverr == 1'b1);
        end
        assert (irq == |(status_q & int_en_q));
        assert (gpio_out == data_out_q[N-1:0]);
        assert (gpio_oe == dir_q[N-1:0]);
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
