`timescale 1ns/1ps
`default_nettype none

// Self-checking testbench for apb_gpio. Detection sections use pins 0..7 (N >= 8).
module apb_gpio_tb;
    parameter N = 8;

    localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

    localparam [7:0] A_DATA_OUT = 8'h00;
    localparam [7:0] A_DIR      = 8'h04;
    localparam [7:0] A_DATA_IN  = 8'h08;
    localparam [7:0] A_RISE     = 8'h0C;
    localparam [7:0] A_FALL     = 8'h10;
    localparam [7:0] A_HIGH     = 8'h14;
    localparam [7:0] A_LOW      = 8'h18;
    localparam [7:0] A_EN       = 8'h1C;
    localparam [7:0] A_STATUS   = 8'h20;

    reg          pclk    = 1'b0;
    reg          presetn = 1'b0;
    reg  [7:0]   paddr   = 8'h00;
    reg          psel    = 1'b0;
    reg          penable = 1'b0;
    reg          pwrite  = 1'b0;
    reg  [31:0]  pwdata  = 32'h0;
    reg  [3:0]   pstrb   = 4'h0;
    wire [31:0]  prdata;
    wire         pready;
    wire         pslverr;
    reg  [N-1:0] gpio_in = {N{1'b0}};
    wire [N-1:0] gpio_out;
    wire [N-1:0] gpio_oe;
    wire         irq;

    integer passed = 0;
    integer failed = 0;
    integer ok;
    integer r;
    reg [8*64-1:0] nonce;
    reg [31:0] model;
    reg [31:0] dref;
    reg [7:0]  rw_addr [0:5];

    apb_gpio #(.ADDR_WIDTH(8), .N(N)) dut (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata), .pready(pready), .pslverr(pslverr),
        .gpio_in(gpio_in), .gpio_out(gpio_out), .gpio_oe(gpio_oe), .irq(irq)
    );

    always #5 pclk = ~pclk;

    // ---------------- check helpers ----------------
    task check(input [31:0] got, input [31:0] exp, input [31:0] id);
        begin
            if (got === exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("check %0d failed: got 0x%08h expected 0x%08h", id, got, exp);
            end
        end
    endtask

    task check_bit(input got, input exp, input [31:0] id);
        begin
            if (got === exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("check %0d failed: got %b expected %b", id, got, exp);
            end
        end
    endtask

    function [31:0] smask(input [3:0] s);
        smask = {{8{s[3]}}, {8{s[2]}}, {8{s[1]}}, {8{s[0]}}};
    endfunction

    task idle(input integer n);
        begin
            repeat (n) @(negedge pclk);
        end
    endtask

    task set_pins(input [31:0] v);
        begin
            gpio_in = v[N-1:0];
        end
    endtask

    // ---------------- APB tasks ----------------
    task apb_write(input [7:0] a, input [31:0] d, input [3:0] s, input exp_err, input [31:0] id);
        begin
            @(negedge pclk);
            psel = 1'b1; penable = 1'b0; pwrite = 1'b1; paddr = a; pwdata = d; pstrb = s;
            #1;
            check_bit(pslverr, 1'b0, id);
            check(prdata, 32'h0, id);
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_bit(pready, 1'b1, id);
            check_bit(pslverr, exp_err, id);
            check(prdata, 32'h0, id);
            @(negedge pclk);
            psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
        end
    endtask

    task apb_read(input [7:0] a, output [31:0] d, output e, input [31:0] id);
        begin
            @(negedge pclk);
            psel = 1'b1; penable = 1'b0; pwrite = 1'b0; paddr = a; pstrb = 4'h0;
            #1;
            check_bit(pslverr, 1'b0, id);
            check(prdata, 32'h0, id);
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_bit(pready, 1'b1, id);
            d = prdata;
            e = pslverr;
            @(negedge pclk);
            psel = 1'b0; penable = 1'b0;
        end
    endtask

    task read_check(input [7:0] a, input [31:0] exp, input exp_err, input [31:0] id);
        reg [31:0] d;
        reg        e;
        begin
            apb_read(a, d, e, id);
            check(d, exp, id);
            check_bit(e, exp_err, id);
        end
    endtask

    task rw_step(input [7:0] a, input [31:0] d, input [3:0] s, input [31:0] id);
        begin
            apb_write(a, d, s, 1'b0, id);
            model = ((model & ~smask(s)) | (d & smask(s))) & PINS;
            read_check(a, model, 1'b0, id);
            if (a == A_DATA_OUT) check_bit(gpio_out === model[N-1:0], 1'b1, id);
            if (a == A_DIR)      check_bit(gpio_oe  === model[N-1:0], 1'b1, id);
            check_bit(irq, 1'b0, id);
        end
    endtask

    // ---------------- protocol monitor ----------------
    always @(posedge pclk) begin
        if (presetn === 1'b1) begin
            if (pready !== 1'b1) begin
                failed = failed + 1;
                $error("monitor: pready not high at %0t", $time);
            end
            if (!(psel && penable) && ((prdata !== 32'h0) || (pslverr !== 1'b0))) begin
                failed = failed + 1;
                $error("monitor: prdata/pslverr nonzero outside access at %0t", $time);
            end
        end
    end

    // ---------------- watchdog ----------------
    initial begin
        #(2000000);
        failed = failed + 1;
        $error("watchdog timeout");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // ---------------- main sequence ----------------
    initial begin
        nonce = {(8*64){1'b0}};
        ok = $value$plusargs("nirmaan_nonce=%s", nonce);

        rw_addr[0] = A_DATA_OUT;
        rw_addr[1] = A_DIR;
        rw_addr[2] = A_RISE;
        rw_addr[3] = A_FALL;
        rw_addr[4] = A_HIGH;
        rw_addr[5] = A_EN;

        // ---- 100: reset values ----
        presetn = 1'b0;
        set_pins(32'h0);
        idle(3);
        check_bit(gpio_out === {N{1'b0}}, 1'b1, 100);
        check_bit(gpio_oe  === {N{1'b0}}, 1'b1, 101);
        check_bit(irq, 1'b0, 102);
        presetn = 1'b1;
        read_check(A_DATA_OUT, 32'h0, 1'b0, 110);
        read_check(A_DIR,      32'h0, 1'b0, 111);
        read_check(A_DATA_IN,  32'h0, 1'b0, 112);
        read_check(A_RISE,     32'h0, 1'b0, 113);
        read_check(A_FALL,     32'h0, 1'b0, 114);
        read_check(A_HIGH,     32'h0, 1'b0, 115);
        read_check(A_LOW,      32'h0, 1'b0, 116);
        read_check(A_EN,       32'h0, 1'b0, 117);
        read_check(A_STATUS,   32'h0, 1'b0, 118);
        check_bit(gpio_out === {N{1'b0}}, 1'b1, 119);
        check_bit(gpio_oe  === {N{1'b0}}, 1'b1, 120);
        check_bit(irq, 1'b0, 121);

        // ---- 200: read/write registers, partial strobes, bits above N ----
        for (r = 0; r < 6; r = r + 1) begin
            model = 32'h0;
            rw_step(rw_addr[r], 32'hFFFF_FFFF, 4'hF, 200 + r*10 + 0);
            rw_step(rw_addr[r], 32'h0000_0000, 4'h1, 200 + r*10 + 1);
            rw_step(rw_addr[r], 32'h1234_5678, 4'hA, 200 + r*10 + 2);
            rw_step(rw_addr[r], 32'hA5A5_A5A5, 4'h5, 200 + r*10 + 3);
            rw_step(rw_addr[r], 32'hFFFF_FFFF, 4'h0, 200 + r*10 + 4);
            rw_step(rw_addr[r], 32'h5A5A_5A5A, 4'hF, 200 + r*10 + 5);
            rw_step(rw_addr[r], 32'h0000_0000, 4'hF, 200 + r*10 + 6);
        end
        read_check(A_STATUS, 32'h0, 1'b0, 270);

        // ---- 280: INTR_LOW (sets status while pins are low) ----
        apb_write(A_LOW, 32'hFFFF_FFFF, 4'hF, 1'b0, 280);
        read_check(A_LOW, PINS, 1'b0, 281);
        read_check(A_STATUS, PINS, 1'b0, 282);
        check_bit(irq, 1'b0, 283);                       // masked, status still set
        apb_write(A_LOW, 32'h0000_0000, 4'h1, 1'b0, 284);
        read_check(A_LOW, PINS & 32'hFFFF_FF00, 1'b0, 285);
        apb_write(A_LOW, 32'h0000_0000, 4'hF, 1'b0, 286);
        read_check(A_LOW, 32'h0, 1'b0, 287);
        apb_write(A_STATUS, 32'hFFFF_FFFF, 4'hF, 1'b0, 288);
        read_check(A_STATUS, 32'h0, 1'b0, 289);

        // ---- 300: DATA_IN, read only ----
        dref = 32'hA5C3_96E1 & PINS;
        set_pins(32'hA5C3_96E1);
        read_check(A_DATA_IN, dref, 1'b0, 300);
        apb_write(A_DATA_IN, 32'hFFFF_FFFF, 4'hF, 1'b1, 301);
        read_check(A_DATA_IN, dref, 1'b0, 302);
        apb_write(A_DATA_IN, 32'h0000_0000, 4'hF, 1'b1, 303);
        read_check(A_DATA_IN, dref, 1'b0, 304);
        set_pins(32'h0);
        idle(2);
        read_check(A_DATA_IN, 32'h0, 1'b0, 305);
        read_check(A_STATUS, 32'h0, 1'b0, 306);          // no enables, no detection

        // ---- 400: PSLVERR policy and unmapped addresses ----
        dref = 32'h3C5A_A55A & PINS;
        apb_write(A_DATA_OUT, 32'h3C5A_A55A, 4'hF, 1'b0, 400);
        apb_write(A_DIR,      32'hC3A5_5AA5, 4'hF, 1'b0, 401);
        apb_write(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1, 402);
        apb_write(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1, 403);  // would alias DATA_OUT
        apb_write(8'h44, 32'h0000_0000, 4'hF, 1'b1, 404);  // would alias DIR
        apb_write(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1, 405);  // unaligned
        apb_write(8'h05, 32'h0000_0000, 4'hF, 1'b1, 406);  // unaligned
        apb_write(8'hFC, 32'hFFFF_FFFF, 4'hF, 1'b1, 407);
        apb_write(8'h3C, 32'hFFFF_FFFF, 4'hF, 1'b1, 408);
        read_check(A_DATA_OUT, dref, 1'b0, 410);
        read_check(A_DIR, 32'hC3A5_5AA5 & PINS, 1'b0, 411);
        check_bit(gpio_out === dref[N-1:0], 1'b1, 412);
        read_check(8'h24, 32'h0, 1'b1, 420);
        read_check(8'h40, 32'h0, 1'b1, 421);
        read_check(8'h44, 32'h0, 1'b1, 422);
        read_check(8'h01, 32'h0, 1'b1, 423);
        read_check(8'h02, 32'h0, 1'b1, 424);
        read_check(8'h3C, 32'h0, 1'b1, 425);
        read_check(8'h80, 32'h0, 1'b1, 426);
        read_check(8'hFF, 32'h0, 1'b1, 427);
        read_check(8'h60, 32'h0, 1'b1, 428);
        apb_write(A_DATA_OUT, 32'h0, 4'hF, 1'b0, 430);
        apb_write(A_DIR,      32'h0, 4'hF, 1'b0, 431);
        check_bit(gpio_out === {N{1'b0}}, 1'b1, 432);
        check_bit(gpio_oe  === {N{1'b0}}, 1'b1, 433);

        // ---- 510: rising edge fires once, interrupt mask ----
        apb_write(A_RISE, 32'h01, 4'hF, 1'b0, 510);
        set_pins(32'h01);
        idle(3);
        read_check(A_STATUS, 32'h01, 1'b0, 511);
        check_bit(irq, 1'b0, 512);                       // masked
        apb_write(A_EN, 32'h01, 4'hF, 1'b0, 513);
        check_bit(irq, 1'b1, 514);
        apb_write(A_STATUS, 32'h01, 4'hF, 1'b0, 515);
        check_bit(irq, 1'b0, 516);
        idle(3);
        read_check(A_STATUS, 32'h0, 1'b0, 517);          // pin held high: no refire
        check_bit(irq, 1'b0, 518);

        // ---- 520: falling edge ----
        apb_write(A_FALL, 32'h02, 4'hF, 1'b0, 520);
        set_pins(32'h03);
        idle(3);
        read_check(A_STATUS, 32'h0, 1'b0, 521);          // rising pin1 not enabled
        set_pins(32'h01);
        idle(3);
        read_check(A_STATUS, 32'h02, 1'b0, 522);
        check_bit(irq, 1'b0, 523);
        apb_write(A_STATUS, 32'h02, 4'hF, 1'b0, 524);
        read_check(A_STATUS, 32'h0, 1'b0, 525);

        // ---- 530: high level sets again after a clear ----
        apb_write(A_HIGH, 32'h04, 4'hF, 1'b0, 530);
        set_pins(32'h05);
        idle(3);
        read_check(A_STATUS, 32'h04, 1'b0, 531);
        apb_write(A_STATUS, 32'h04, 4'hF, 1'b0, 532);
        read_check(A_STATUS, 32'h04, 1'b0, 533);         // level still holds
        apb_write(A_HIGH, 32'h0, 4'hF, 1'b0, 534);
        apb_write(A_STATUS, 32'h04, 4'hF, 1'b0, 535);
        read_check(A_STATUS, 32'h0, 1'b0, 536);
        set_pins(32'h01);
        idle(2);
        read_check(A_STATUS, 32'h0, 1'b0, 537);

        // ---- 540: low level ----
        apb_write(A_LOW, 32'h08, 4'hF, 1'b0, 540);
        idle(1);
        read_check(A_STATUS, 32'h08, 1'b0, 541);
        apb_write(A_STATUS, 32'h08, 4'hF, 1'b0, 542);
        read_check(A_STATUS, 32'h08, 1'b0, 543);         // level still holds
        set_pins(32'h09);
        idle(3);
        apb_write(A_STATUS, 32'h08, 4'hF, 1'b0, 544);
        read_check(A_STATUS, 32'h0, 1'b0, 545);
        apb_write(A_LOW, 32'h0, 4'hF, 1'b0, 546);
        check_bit(irq, 1'b0, 547);

        // ---- 600: write-1-to-clear of some pending bits only ----
        apb_write(A_RISE, 32'hF1, 4'hF, 1'b0, 600);
        set_pins(32'hF9);
        idle(3);
        read_check(A_STATUS, 32'hF0, 1'b0, 601);
        check_bit(irq, 1'b0, 602);                       // only bit 0 enabled
        apb_write(A_STATUS, 32'h30, 4'hF, 1'b0, 603);
        read_check(A_STATUS, 32'hC0, 1'b0, 604);
        apb_write(A_STATUS, 32'hFFFF_FFFF, 4'h0, 1'b0, 605); // no strobes
        read_check(A_STATUS, 32'hC0, 1'b0, 606);
        apb_write(A_STATUS, 32'hFFFF_FF00, 4'h2, 1'b0, 607); // byte 0 unstrobed
        read_check(A_STATUS, 32'hC0, 1'b0, 608);
        apb_write(A_STATUS, 32'h40, 4'h1, 1'b0, 609);
        read_check(A_STATUS, 32'h80, 1'b0, 610);
        apb_write(A_EN, 32'h80, 4'hF, 1'b0, 611);
        check_bit(irq, 1'b1, 612);
        apb_write(A_EN, 32'h01, 4'hF, 1'b0, 613);
        check_bit(irq, 1'b0, 614);                       // masked
        apb_write(A_STATUS, 32'h80, 4'hF, 1'b0, 615);
        read_check(A_STATUS, 32'h0, 1'b0, 616);
        check_bit(irq, 1'b0, 617);

        // ---- 700: detection beats a clear on the same edge ----
        set_pins(32'hF8);
        idle(3);
        set_pins(32'hF9);
        idle(3);
        read_check(A_STATUS, 32'h01, 1'b0, 700);
        check_bit(irq, 1'b1, 701);
        set_pins(32'hF8);
        idle(3);
        read_check(A_STATUS, 32'h01, 1'b0, 702);
        // Rise on pin 0 sampled on the setup edge, detected on the clearing edge.
        @(negedge pclk);
        set_pins(32'hF9);
        psel = 1'b1; penable = 1'b0; pwrite = 1'b1; paddr = A_STATUS;
        pwdata = 32'h01; pstrb = 4'hF;
        @(negedge pclk);
        penable = 1'b1;
        #1;
        check_bit(pslverr, 1'b0, 703);
        @(negedge pclk);
        psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
        read_check(A_STATUS, 32'h01, 1'b0, 704);
        check_bit(irq, 1'b1, 705);
        apb_write(A_STATUS, 32'h01, 4'hF, 1'b0, 706);
        read_check(A_STATUS, 32'h0, 1'b0, 707);
        check_bit(irq, 1'b0, 708);

        // ---- 800: reset again ----
        apb_write(A_DATA_OUT, 32'hFFFF_FFFF, 4'hF, 1'b0, 800);
        apb_write(A_DIR,      32'hFFFF_FFFF, 4'hF, 1'b0, 801);
        apb_write(A_HIGH,     32'h80,        4'hF, 1'b0, 802);
        apb_write(A_EN,       32'h80,        4'hF, 1'b0, 803);
        idle(2);
        check_bit(irq, 1'b1, 804);
        check_bit(gpio_out === PINS[N-1:0], 1'b1, 805);
        check_bit(gpio_oe  === PINS[N-1:0], 1'b1, 806);
        set_pins(32'h0);
        presetn = 1'b0;
        idle(2);
        check_bit(gpio_out === {N{1'b0}}, 1'b1, 810);
        check_bit(gpio_oe  === {N{1'b0}}, 1'b1, 811);
        check_bit(irq, 1'b0, 812);
        presetn = 1'b1;
        read_check(A_DATA_OUT, 32'h0, 1'b0, 820);
        read_check(A_DIR,      32'h0, 1'b0, 821);
        read_check(A_DATA_IN,  32'h0, 1'b0, 822);
        read_check(A_RISE,     32'h0, 1'b0, 823);
        read_check(A_FALL,     32'h0, 1'b0, 824);
        read_check(A_HIGH,     32'h0, 1'b0, 825);
        read_check(A_LOW,      32'h0, 1'b0, 826);
        read_check(A_EN,       32'h0, 1'b0, 827);
        read_check(A_STATUS,   32'h0, 1'b0, 828);
        check_bit(gpio_out === {N{1'b0}}, 1'b1, 829);
        check_bit(gpio_oe  === {N{1'b0}}, 1'b1, 830);
        check_bit(irq, 1'b0, 831);

        idle(2);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

